// Server capability discovers editable lead proposals; local selection is never membership.
let intakeTeamLeadDraft=null;
const intakeTeamSafeId=v=>typeof v==='string'&&/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(v);
function intakeTeamLeadReferences(){const a=db?.intakeTeamAccess;if(a?.enabled!==true||!Array.isArray(a.leadProposals))return [];return a.leadProposals.filter(p=>p&&intakeTeamSafeId(p.proposalId)&&intakeTeamSafeId(p.leadStudentId)&&Number.isSafeInteger(p.proposalVersion)&&p.proposalVersion>0&&Number.isSafeInteger(p.teamRevision)&&p.teamRevision>=0&&a.leadProposals.filter(q=>q?.proposalId===p.proposalId).length===1).slice(0,100)}
function intakeTeamLeadPanel(){const ps=intakeTeamLeadReferences();if(!ps.length)return '';return `<section class="panel"><h2>Build your proposed team</h2><p>Search eligible students, then select whom you wish to invite. Selection alone does not add members.</p>${ps.map((p,i)=>`<button type="button" data-team-lead-index="${i}">Select students · ${esc(p.proposalId)}</button>`).join('')}</section>`}
function intakeTeamLeadCurrent(d){const p=intakeTeamLeadReferences().find(p=>p.proposalId===d.proposalId);return intakeTeamLeadDraft===d&&sharedReady&&uid===d.actor&&sharedActor===d.actor&&sharedRevision===d.revision&&page==='Activity Intake'&&p?.proposalVersion===d.proposalVersion&&p.teamRevision===d.teamRevision&&p.leadStudentId===d.leadStudentId}
function openIntakeTeamSearch(proposalId){if(!sharedReady||sharedBusy)return;const p=intakeTeamLeadReferences().find(p=>p.proposalId===proposalId);if(!p)return toast('Team selection is unavailable. Refresh your workspace.');const d={...p,actor:sharedActor,revision:sharedRevision,query:'',rows:[],nextOffset:null,offset:0,selected:new Map(),message:'Search by student name or ID (at least two characters).'};intakeTeamLeadDraft=d;renderIntakeTeamSearch(d)}
function renderIntakeTeamSearch(d){if(!intakeTeamLeadCurrent(d))return;modal(`<h2>Select proposed team members</h2><p>${esc(d.proposalId)} · The lead is included separately. Only students returned by the authorized directory can be selected.</p><form id="intake-team-search-form"><label>Student name or ID<input name="query" required minlength="2" maxlength="120" value="${esc(d.query)}" autocomplete="off"></label><button type="submit">Search students</button></form><p role="status" id="intake-team-search-status">${esc(d.message)}</p><div>${d.rows.map((s,i)=>`<label><input type="checkbox" data-team-row="${i}" ${d.selected.has(s.studentId)?'checked':''}> ${esc(s.displayName)} · ${esc(s.studentId)}<small> ${esc(s.programmeId)} · ${esc(s.batchId)} · ${esc(s.semesterId)}</small></label>`).join('')}</div><div id="intake-team-search-pages" class="buttons"></div><h3>Selected students (${d.selected.size})</h3><div id="intake-team-selected"></div><p>These selections are temporary and have not sent invitations. Each invited student must accept before becoming a confirmed member.</p>${intakeTeamPreparationForm(d)}`);
 const confirmation=document.querySelector('#intake-team-confirmation-form');if(confirmation)confirmation.onsubmit=e=>{e.preventDefault();prepareSelectedIntakeTeam(d,new FormData(e.target).get('confirmed')==='yes')};
 const form=document.querySelector('#intake-team-search-form');form.onsubmit=e=>{e.preventDefault();searchIntakeTeamStudents(d,new FormData(e.target).get('query'),0)};
 for(const node of document.querySelectorAll('[data-team-row]'))node.onchange=()=>selectIntakeTeamStudent(d,Number(node.dataset.teamRow),node.checked);
 const pages=document.querySelector('#intake-team-search-pages');for(const [title,offset] of [['Previous page',d.offset>=20?d.offset-20:null],['Next page',d.nextOffset]])if(offset!==null){const b=document.createElement('button');b.type='button';b.textContent=title;b.onclick=()=>searchIntakeTeamStudents(d,d.query,offset);pages.append(b)}
 const selected=document.querySelector('#intake-team-selected');for(const s of d.selected.values()){const b=document.createElement('button');b.type='button';b.textContent='Remove '+s.displayName+' · '+s.studentId;b.onclick=()=>{if(intakeTeamLeadCurrent(d)&&!sharedBusy){d.selected.delete(s.studentId);renderIntakeTeamSearch(d)}};selected.append(b)}
}
function selectIntakeTeamStudent(d,index,checked){if(!intakeTeamLeadCurrent(d)||sharedBusy||!$('#modal').open)return;const s=d.rows[index];if(!Number.isSafeInteger(index)||!s)return;if(checked){if(d.selected.size>=99&&!d.selected.has(s.studentId)){d.message='Select up to 99 other students.';return renderIntakeTeamSearch(d)}d.selected.set(s.studentId,{...s})}else d.selected.delete(s.studentId);renderIntakeTeamSearch(d)}
function validIntakeTeamDirectory(r,d){const a=r?.directory;return intakeTeamResponseValid(r,d,'DIRECTORY')&&r.revision===d.revision&&a?.proposalId===d.proposalId&&a.proposalVersion===d.proposalVersion&&a.membershipGranted===false&&Array.isArray(a.rows)&&a.rows.length<=20&&new Set(a.rows.map(s=>s?.studentId)).size===a.rows.length&&a.rows.every(s=>s&&intakeTeamSafeId(s.studentId)&&s.studentId!==d.leadStudentId&&Number.isSafeInteger(s.studentVersion)&&s.studentVersion>0&&typeof s.displayName==='string'&&s.displayName.trim()&&s.displayName.length<=200&&['departmentId','programmeId','batchId','semesterId'].every(k=>intakeTeamSafeId(s[k])))&&(a.nextOffset===null||Number.isSafeInteger(a.nextOffset)&&a.nextOffset>=0&&a.nextOffset<=10000)}
async function searchIntakeTeamStudents(d,query,offset){if(!intakeTeamLeadCurrent(d)||sharedBusy||!$('#modal').open)return;const q=typeof query==='string'?query.normalize('NFKC').trim():'';if(q.length<2||q.length>120||/[\u0000-\u001f]/.test(q)||!Number.isSafeInteger(offset)||offset<0||offset>10000)return toast('Enter 2–120 characters and use the available page controls.');const form=document.querySelector('#intake-team-search-form');lockShared(true);try{const r=await sharedFetch('/api/workspace',{command:'searchIntakeTeamStudents',actor:d.actor,revision:d.revision,args:[{proposalId:d.proposalId,query:q,filters:{},offset,limit:20}],context:{page:'Activity Intake'}});if(!intakeTeamLeadCurrent(d)||!$('#modal').open||document.querySelector('#intake-team-search-form')!==form)return;if(!validIntakeTeamDirectory(r,d)||r.directory.nextOffset!==null&&r.directory.nextOffset!==offset+20)throw Error('Directory results changed or are unavailable. Refresh before retrying.');
 for(const s of r.directory.rows){const old=d.selected.get(s.studentId);if(old&&old.studentVersion!==s.studentVersion){d.selected.delete(s.studentId)}}
 // Pick only the directory display contract, even if a malformed service adds fields.
 d.rows=r.directory.rows.map(s=>Object.fromEntries(['studentId','studentVersion','displayName','departmentId','programmeId','batchId','semesterId'].map(k=>[k,s[k]])));d.query=q;d.offset=offset;d.nextOffset=r.directory.nextOffset;d.message=d.rows.length?'Select students to add to your proposed invitation list.':'No matching eligible students in this scope.';renderIntakeTeamSearch(d);
 }catch(e){if(intakeTeamLeadCurrent(d)&&$('#modal').open&&document.querySelector('#intake-team-search-form')===form){d.rows=[];d.selected.clear();d.nextOffset=null;d.offset=0;d.message=e.message+' Refresh and search again before selecting.';renderIntakeTeamSearch(d)}}finally{lockShared(false)}}
document.addEventListener('click',event=>{const b=event.target.closest?.('[data-team-lead-index]');if(!b)return;const i=Number(b.dataset.teamLeadIndex),ps=intakeTeamLeadReferences();if(Number.isSafeInteger(i)&&i>=0&&i<ps.length)openIntakeTeamSearch(ps[i].proposalId)});
function resetIntakeTeamLeadSelection(){intakeTeamLeadDraft=null;if(document.querySelector('#intake-team-search-form')&&$('#modal').open)closeModal()}
function intakeTeamPreparationAction(d){const p=intakeTeamLeadReferences().find(p=>p.proposalId===d.proposalId);if(!intakeTeamLeadCurrent(d)||p?.canPrepareInvitations!==true||p.invitationAction!==d.invitationAction)return null;return p.invitationAction==='CREATE'&&d.teamRevision===0?'CREATE':p.invitationAction==='REVISE'&&d.teamRevision>0?'REVISE':null}
function intakeTeamPreparationForm(d){const action=intakeTeamPreparationAction(d);if(!action||!d.selected.size)return '';return `<form id="intake-team-confirmation-form"><h3>Confirm invitation list</h3><p>Lead: ${esc(d.leadStudentId)} · ${d.selected.size} other student(s). This is the complete proposed list for this round.</p><ul>${[...d.selected.values()].map(s=>`<li>${esc(s.displayName)} · ${esc(s.studentId)}</li>`).join('')}</ul>${action==='REVISE'?'<p>A replacement round retains prior history and requires fresh acceptance from every other student. Prior acceptances do not carry forward.</p>':''}<label><input type="checkbox" name="confirmed" value="yes" required> I have reviewed the full list and want to ${action==='CREATE'?'prepare these invitations':'replace the invitation round'}.</label><button type="submit">${action==='CREATE'?'Prepare invitations':'Confirm replacement round'}</button><p>Preparing invitations does not approve the project, grant execution permission or confirm other students as members. Notification delivery is a separate process.</p></form>`}
async function prepareSelectedIntakeTeam(d,confirmed){const action=intakeTeamPreparationAction(d);if(!action||!confirmed||sharedBusy||!$('#modal').open||!d.selected.size||d.selected.size>99)return toast('Review the current list and confirm before preparing invitations.');const ids=[d.leadStudentId,...d.selected.keys()];if(ids.some(id=>!intakeTeamSafeId(id))||new Set(ids).size!==ids.length)return toast('The selection changed. Search and review again.');const form=document.querySelector('#intake-team-confirmation-form');if(!form)return;lockShared(true);let saved=false;try{
 const r=await sharedFetch('/api/workspace',{command:action==='CREATE'?'prepareIntakeTeamInvitations':'reviseIntakeTeamInvitations',actor:d.actor,revision:d.revision,args:[{proposalId:d.proposalId,expectedTeamRevision:d.teamRevision,memberIds:ids}],context:{page:'Activity Intake'}});
 if(!intakeTeamLeadCurrent(d)||!intakeTeamResponseValid(r,d,action)||r.revision!==d.revision+1||r.team?.ok!==true||r.team.proposalId!==d.proposalId||r.team.workspaceRevision!==r.revision||r.team.teamRevision!==d.teamRevision+1)throw Error('Invitation result is unavailable.');saved=true;
 const fresh=await sharedFetch('/api/workspace');if(!intakeTeamLeadCurrent(d)||fresh?.actor!==d.actor||!Number.isSafeInteger(fresh.revision)||fresh.revision<r.revision||!Array.isArray(fresh.data?.projects))throw Error('A fresh workspace is required.');
 // A dedicated invitation result never replaces the main workspace snapshot.
 resetIntakeTeamLeadSelection();applyShared(fresh);toast('Invitation round saved. Other students must accept; project approval and notification delivery remain separate.');
 }catch(e){if(intakeTeamLeadDraft===d){resetIntakeTeamLeadSelection()}toast((saved?'Invitations were saved, but the workspace could not refresh. ':'The result could not be confirmed. ')+e.message+' Refresh and review the current round before retrying.')}finally{lockShared(false)}}
